const layoutId = target.id;
if (target === options.currentTarget) {
	return;
}

const selectedLayout = options.currentTarget.data.get(layoutId);
const { setCurrentLayout, updateLayoutData } = options.getActions();
setCurrentLayout(layoutId);
updateLayoutData(structuredClone(selectedLayout.settings));

// .setAml() should be called when current search mode is "Simple" to add columns that not exists in current layout but have search criteria
// This columns will be appended at the end of grid
if (currentSearchMode.name === 'Simple') {
	currentSearchMode.setAml(await currentSearchMode.getAml());
}
